"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[8853],{8853:function(e,t,a){a.d(t,{Ey:function(){return f}});let o=["Reserve Bank of India","https://www.rbi.org.in"],r=["Income Tax Department","https://incometaxindia.gov.in"],s=["Startup India","https://www.startupindia.gov.in"],n=["Ministry of MSME (Udyam)","https://udyamregistration.gov.in"],i=["Reserve Bank of India","https://www.rbi.org.in"],h={"dpiit-startup-recognition-guide":{h:"A short readiness checklist",ps:["Before you apply, check five things. First, confirm your entity type and incorporation date against the current notification. Second, confirm that your turnover in every year is within the stated limit. Third, write two or three sentences on what is new or scalable about your business, using specifics such as the problem, the method and the customer. Fourth, make sure your incorporation objects and your website describe the same business. Fifth, keep your director or partner details and PAN ready.","Founders sometimes apply first and fix the description after a query. It is faster to prepare the description before you apply, because a vague first submission tends to attract questions that delay the certificate by weeks."]},"dscr-explained":{h:"Reading DSCR in a projection",ps:["A final tip: when you present DSCR to a bank, show the calculation line by line for each year, with the inputs taken from your projected statements. A clear working invites trust, while a single unexplained figure invites questions about how it was reached.","In a typical term-loan projection, the first year after disbursement often shows the lowest DSCR, because the business is still ramping up while instalments have started. As profits grow and interest falls with the outstanding balance, DSCR improves. If your projection shows the opposite, with DSCR falling in later years, check whether capital spending or a step-up in costs is the cause and whether it is realistic.","Also compare DSCR with your cash balance. A business with a thin DSCR but a healthy cash reserve may be able to manage a weak year, while one with a good DSCR and no reserve can still be caught by a delayed payment. Banks look at both, so show your cash plan alongside the ratio."]},"financial-projections-for-cc-od-or-term-loan":{h:"A simple way to build the first draft",ps:["Before you submit, ask a colleague or adviser to read the projections cold and explain them back to you. If they cannot follow the logic from sales to cash, a credit officer will struggle too, and a short note of assumptions on the first page will help.","Begin with a one-page summary for each year: sales, gross profit, operating profit, interest, tax and profit after tax. Then add the balance sheet items that move with sales: inventory, receivables and creditors, using your holding periods. Add capital spending and the loan schedule. Finally, check that cash from operations, less capital spending and repayments, leaves a positive cash balance each year.","Build this in a spreadsheet where each assumption sits in one cell and every number in the tables is a formula. Then you can change a single assumption, such as sales growth, and see the effect on profit, cash and DSCR immediately. When the draft balances, review each assumption against your history and write one line of reasoning for it. These lines become the notes the bank reads."]},"gst-registration-documents-checklist":{h:"Preparing the application",ps:["Scan every document in a clear, readable format and check the file size limits on the portal. Name files so that you can find them quickly, and keep the originals handy for a possible verification. Make sure the mobile number and email used for the application belong to the applicant or the authorised signatory, because verification codes are sent there.","If the officer raises a query, reply with the document requested and a short explanation, within the time given. A clear reply usually resolves the query without a second round."]},"pitch-deck-for-indian-investors":{h:"Tailoring the deck to the investor",ps:["An angel investor reading a deck for a first meeting wants to see whether the problem is real and whether you can execute. A venture fund will look more closely at market size, the path to a large outcome and unit economics. A strategic investor will want to know how you fit with their business. Keep one core deck and adjust the emphasis, the order of slides and the opening lines for each audience.","Whoever you pitch to, keep a longer appendix ready: detailed financial assumptions, customer references, product screens and the cap table. Share it when asked, not before."]},"project-report-vs-cma-report":{h:"A worked scenario",ps:["Whichever documents your bank requires, ask in advance for its checklist and its CMA format. A fifteen-minute call with the relationship manager can save weeks of rework.","Consider a manufacturer that wants to add a new production line and also needs a larger cash credit limit. The bank is likely to ask for a project report for the line, covering the machinery, its cost, the funding split, the market for the extra output and the repayment plan. It will also ask for CMA data for the enlarged business, which shows the combined operating statement, balance sheet and working capital need after the expansion.","If these are prepared separately, small differences creep in: the project report may assume the line starts in April and the CMA in June, or the project cost may differ by a few lakh. A single model avoids this, and it lets you answer the bank's questions with confidence because every figure traces back to the same assumption."]},"tender-eligibility-documents-checklist":{h:"Keeping a master file",ps:["When you are unsure whether a document meets a clause, raise a pre-bid query in writing before the deadline. Tendering authorities usually publish the clarification to all bidders, which protects you from an unexpected rejection.","MSMEs that bid regularly save time by keeping a master folder: registrations, the last three years of audited financials, turnover certificates, completion certificates, ISO certificates, bank solvency letters and sample declarations. Update it every quarter and note the expiry date of each document. Before each bid, copy the relevant items into the tender folder and check them against the clauses.","A calendar reminder for renewals, such as the digital signature certificate and certifications, prevents the most avoidable kind of rejection, an expired document on the last day."]},"valuing-unquoted-shares-rule-11ua":{h:"A note on documentation",ps:["Whatever the valuation basis, keep the paperwork: the valuation report, the financial statements used, the board resolution approving the price and the share transfer or allotment documents. If the tax department or the Registrar later questions a price, a dated report with its working is the first thing you will need."]}},c=["Reserve Bank of India","https://www.rbi.org.in"],d=["Indian Banks' Association","https://www.iba.org.in"],l=["Ministry of MSME","https://msme.gov.in"],u=["Ministry of Corporate Affairs","https://www.mca.gov.in"],p=["Startup India","https://www.startupindia.gov.in"],m={date:"November 2026",iso:"2026-11-16",updated:"2026-11-16",author:"Harivadan Dabhi"};[{slug:"cma-report-for-a-bank-loan",title:"CMA Report for a Bank Loan: Format, Documents and Common Mistakes",short:"CMA report for a bank loan",desc:"How to prepare a CMA report for a bank loan: the format, documents, how to set projections and the mistakes that make banks send reports back.",date:"November 2026",iso:"2026-11-02",author:"Harivadan Dabhi",service:["business-valuation","cma-report"],tool:"dscr-calculator",related:["what-is-a-cma-report","financial-projections-for-cc-od-or-term-loan","project-report-vs-cma-report"],checklist:["CMA report document checklist","/downloads/cma-report-document-checklist.pdf"],sources:[o,["Indian Banks' Association","https://www.iba.org.in"],["Ministry of MSME","https://msme.gov.in"]],sections:[{h:"What the bank wants from your report",ps:["When you apply for a working capital limit or a term loan, the credit officer has to answer three questions: how much does this business need, how will it use the money and how will it repay. A CMA report answers all three in a format the bank can compare with other borrowers.","A strong report is not a longer report. It is one where every number agrees with every other number, every assumption has a reason and the story the figures tell matches what the officer sees in your bank statements and GST returns. This guide walks through how to prepare one."]},{h:"Start with the right facility",ps:["Decide what you are asking for before you build numbers. A cash credit or overdraft limit finances day-to-day working capital and moves up and down with use. A term loan finances assets such as machinery and is repaid in instalments. Some businesses need both, and the report must show each separately.","Ask your bank for its CMA format and the number of years it wants. Banks usually want two to three years of past results, an estimate for the current year and projections for the next two to five years, with term loans needing projections for the full repayment period."]},{h:"Gather the documents first",ps:["Collect documents before you build projections, because they decide what you can credibly project."],ul:["Audited or provisional financial statements for the last two to three years, with schedules.","The current year's results to date and a stock statement.","Debtor and creditor lists with ageing.","Bank statements for 12 months and sanction letters for existing loans.","GST returns and income tax returns, so figures can be cross-checked.","Quotations for machinery or capital items if you are asking for a term loan."]},{h:"Build projections that follow from your history",ps:["Start from last year's actual results and move forward with stated reasons. If you project sales to grow 30 per cent while history shows 8 per cent, write down what changes: a new order, a new plant, a new market. If margins improve, say why: lower material cost, better pricing, scale.","Keep working capital days consistent with your real cycle. If your debtors take 60 days to pay today, projecting 30 days needs a reason. Banks notice when holding periods change from year to year without explanation."]},{h:"The forms the bank reads",ps:["The CMA format has six forms covering existing and proposed limits, the operating statement, the balance sheet analysis, the comparison of current assets and liabilities, the MPBF calculation and the fund flow. You can see a worked example in our [sample CMA report](/sample-reports/cma-report/), which uses a fictional company.","Each form depends on the one before it, so an error in the operating statement flows through to the ratios and the MPBF. That is why the best way to prepare a CMA is in one linked Excel model, not as six separate tables."]},{h:"Check the ratios before the bank does",ps:["Calculate the current ratio, the debt-to-net-worth ratio, the interest coverage ratio and the debt service coverage ratio for every year. Compare them with the norms your bank is likely to use. If a ratio falls outside the norm in a projected year, either change the plan or add a note that explains it. Our [DSCR calculator](/tools/dscr-calculator/) helps you check repayment cover year by year."]},{h:"Common mistakes that cause a report to be returned",ul:["Projections that do not follow from the past with no explanation.","A balance sheet that does not balance, or totals that do not match schedules.","Different holding periods used in different years.","Figures that do not match GST returns or bank statements.","Missing notes on assumptions.","Asking for a limit that is far above the MPBF without supporting reasons.","Forgetting existing loans, guarantees or related-party balances."]},{h:"What happens after you submit",ps:["The bank reviews the data, may ask questions, may visit your premises and prepares a credit note. It may sanction the limit you asked for, a lower limit or different terms. If the bank sends the report back, read the query carefully, correct the numbers and resubmit with a note explaining the change.","We prepare CMA data in your bank's format and walk you through it so you can answer questions on your own. We cannot promise a sanction, since the decision rests with the bank."]}],faq:[["How many years of data does a bank want?","Usually two to three years of past results, the current year's estimate and projections for the next two to five years. Check your bank's format."],["Can I prepare a CMA myself?","Yes, if you know the format and your numbers are clean. Many businesses get help because errors cause delays."],["How long does it take to prepare?","It depends on how ready your records are. With complete documents, the first draft can be ready in several working days."],["What if the bank sanctions less than I asked for?","You can discuss the reasons, adjust the plan or provide more evidence. The decision stays with the bank."],["Do I need audited accounts?","Banks usually prefer audited accounts for past years. Provisional figures may be accepted for the current year."]]},{slug:"how-startups-are-valued-in-india",title:"How Startups Are Valued in India: DCF, Comparables and Other Methods",short:"How startups are valued",desc:"How startups are valued in India: DCF, comparable companies, net asset value and other methods, when each fits and how to prepare for a valuation.",date:"November 2026",iso:"2026-11-02",author:"Harivadan Dabhi",service:["business-valuation","startup-company-valuation"],tool:"dcf-valuation-calculator",related:["valuing-unquoted-shares-rule-11ua","pitch-deck-for-indian-investors","financial-projections-for-cc-od-or-term-loan"],checklist:["Valuation document checklist","/downloads/valuation-document-checklist.pdf"],sources:[["Ministry of Corporate Affairs: valuation rules","https://www.mca.gov.in"],r,["IBBI (Registered Valuers)","https://ibbi.gov.in"]],sections:[{h:"Why valuing a startup is hard",ps:["A mature business can be valued on its past profits. A startup often has little history, losses today and a story about the future. A valuation turns that story into a number by making assumptions explicit, testing them and showing the range of reasonable values.","No valuation is exact. Two competent valuers can reach different figures because they make different assumptions. What matters is that the assumptions are written down, reasonable for the stage and consistent with the evidence. This guide explains the main methods and when each is used in India."]},{h:"Discounted cash flow (DCF)",ps:["DCF estimates the value of a business as the present value of the cash it will produce in future. You project free cash flow for several years, discount each year at a rate that reflects the risk and add a terminal value for the years beyond the forecast.","It works best when you have a credible forecast and reasonable visibility on costs and growth. It is very sensitive to the discount rate and the terminal growth rate, so a good report shows a sensitivity table. For very early startups with no revenue, a DCF depends so much on assumptions that it should be used with another method. Our free [DCF valuation calculator](/tools/dcf-valuation-calculator/) lets you try the mechanics."]},{h:"Comparable companies and transactions",ps:["This method values the business by comparing it with similar companies, using multiples such as revenue or EBITDA, or with similar deals. It is quick to explain and reflects what the market pays.","It works only where good peer data exists. In India, listed peers of a young startup are often much larger, and private deal data is limited, so the choice of peers needs care and a discount for size and liquidity may be needed. A multiple is an input, not an answer."]},{h:"Net asset value and other methods",ps:["Net asset value values the business on what it owns less what it owes. It suits asset-heavy or loss-making companies and often sets a floor in a valuation, but it says little about earning power.","Other approaches are used for early-stage companies: the venture capital method works back from an exit value and the return an investor wants, and the scorecard or checklist methods compare the startup with typical funded companies at its stage. They are used in negotiations and as cross-checks."]},{h:"Which method fits which stage",ps:["Use this as a general guide, not a rule."],table:{head:["Stage","Usual approach","Watch out for"],rows:[["Idea or pre-revenue","Venture capital or scorecard method, as a negotiation guide","Very high uncertainty; weak evidence"],["Early revenue","Revenue multiples with a DCF cross-check","Short history; growth that may not last"],["Growing with margins","DCF plus comparable companies","Terminal value dominating the result"],["Mature or asset-heavy","DCF or net asset value, with comparables","Stale asset values"]]}},{h:"What goes into a good valuation report",ul:["A clear purpose and valuation date.","The information relied on and its source.","A review of the projections against history and the market.","A documented build-up of the discount rate.","Each method's working, a reconciliation and weights, with reasons.","A sensitivity table and a plain statement of limitations."],ps:["You can see this structure in our [sample startup valuation report](/sample-reports/startup-valuation-report/), which uses a fictional company."]},{h:"When a registered valuer is required",ps:["For some purposes the law requires a valuation by a registered valuer or a SEBI-registered merchant banker. Examples include certain valuations under the Companies Act and the Insolvency and Bankruptcy Code and some tax and foreign exchange purposes. For a private negotiation with investors, a registered valuer is usually not required, but the investor may ask for one.","We prepare the analysis and the report, and where a registered signature is required, a licensed professional reviews and signs. We tell you this in the written scope before work begins."]},{h:"How to prepare",ps:["Have your financial statements, your projections with assumptions, your cap table and shareholder agreements and the purpose of the valuation ready. Be ready to explain every step change in growth or margin. The better your records, the shorter the process and the stronger the result. See our [methodology page](/how-we-value-a-business/) for how we review a valuation before it is released."]}],faq:[["What is the best method to value a startup?","There is no single best method. DCF suits companies with forecasts, comparables suit those with good peer data and early-stage methods guide negotiation. Reports often combine two or more."],["How much is my startup worth?","That depends on your numbers, stage, market and the purpose. A valuation report gives a range with its assumptions."],["Do investors accept a founder-prepared valuation?","They may use it as a starting point, but they usually run their own analysis. A documented report from a third party can speed up negotiation."],["Is a valuation report valid forever?","No. It is as at a stated date. Material events or the passage of time can change the value, and some uses require a recent report."]]},{slug:"valuing-unquoted-shares-rule-11ua",title:"Valuing Unquoted Shares: Rule 11UA (Now Rule 57) and What Founders Need to Know",short:"Valuing unquoted shares, Rule 11UA",desc:"How unquoted shares are valued for tax in India: what Rule 11UA covered, how Rule 57 replaces it from April 2026 and where company law valuations apply.",date:"November 2026",iso:"2026-11-02",author:"Harivadan Dabhi",service:["business-valuation","startup-company-valuation"],tool:"dcf-valuation-calculator",related:["how-startups-are-valued-in-india","private-limited-llp-or-opc","pitch-deck-for-indian-investors"],sources:[r,["Ministry of Corporate Affairs","https://www.mca.gov.in"],["Income-tax Act, 2025 (India Code)","https://www.indiacode.nic.in"]],sections:[{h:"Why this rule matters to founders",ps:["When a company issues or transfers shares that are not listed on a stock exchange, the price can have tax consequences for the company, the buyer or the seller. Indian tax law therefore sets rules for working out the fair market value of unquoted shares and compares the price actually paid with that value.","For years, those rules sat in Rule 11UA of the Income-tax Rules, 1962. The Income-tax Act, 2025 came into force on 1 April 2026 and replaced the 1961 Act, with the Income-tax Rules, 2026 as the new framework. Share valuation now sits in Rule 57 of the 2026 Rules. This guide explains the idea in plain language and flags what to confirm with a professional."]},{h:"What changed with the new Act",ps:["Two changes matter. First, the Income-tax Act, 2025 applies to income from tax year 2026-27 onward, while the 1961 Act continues to govern earlier years and pending proceedings. A transaction may therefore fall under either Act depending on its date and the year it relates to.","Second, the tax on share premium received by a company from resident investors in excess of fair value, widely called angel tax and found in section 56(2)(viib) of the 1961 Act, was abolished with effect from 1 April 2025 by the Finance Act, 2024. The 2025 Act has no equivalent provision. For startups raising equity from resident investors, the main reason people feared Rule 11UA no longer applies, but valuation rules still matter in other situations."]},{h:"Where fair value still matters",ps:["Valuation of unquoted shares under the tax rules still matters when shares are transferred for less than fair value, where a share transfer is part of a slump sale or business transfer, for ESOP perquisite calculations and for certain offshore transfers and transfer pricing situations. In each case, the law prescribes how fair value is worked out or accepted.","The rule historically offered formula-based methods for unquoted equity shares, based on the book value of assets and liabilities, and allowed a discounted cash flow valuation by a merchant banker or an accountant in certain cases. Check the current Rule 57 text and the specific provision that applies before relying on any method."]},{h:"Who can certify the valuation",ps:["The rules name the professionals whose reports are accepted for specific purposes. For share valuation under the tax rules, a SEBI-registered Category I merchant banker is named, and for certain purposes a chartered accountant's certificate is accepted. For business transfers such as slump sales, reports from registered valuers and certificates from chartered accountants have defined roles.","The right professional depends on the provision, so confirm which one applies to your transaction. AlphaZet prepares the analysis and coordinates a licensed professional where a signature is required."]},{h:"Company law is a separate test",ps:["Tax rules are not the only ones. Under company law, a preferential allotment of shares or an allotment for consideration other than cash generally requires a valuation by a registered valuer, and a private placement has its own conditions. Foreign exchange rules also set pricing requirements when a non-resident subscribes to or buys shares in an Indian company.","These requirements sit alongside tax rules, so a single transaction can need more than one valuation basis. Plan this before you issue shares, not after."]},{h:"Practical steps for founders",ul:["Decide the purpose of the valuation first: tax, company law, foreign exchange or negotiation.","Confirm which Act and which rules apply to the date of your transaction.","Prepare financial statements, projections and the cap table in advance.","Keep the valuation date close to the transaction date, as the value is as at a stated date.","Document why the price you chose is reasonable, especially if it differs from the valuation.","Keep the report and the supporting working with your records."]},{h:"How we help",ps:["We prepare valuation reports with the working shown and coordinate with licensed professionals where the law requires a signature. We do not give tax opinions in this guide, and the position can change with rules, notifications and circulars, so confirm the current rule and your facts before acting. You can read how we structure a report in our [sample startup valuation report](/sample-reports/startup-valuation-report/)."]}],faq:[["Is Rule 11UA still in force?","For income from tax year 2026-27 onward, valuation rules sit in Rule 57 of the Income-tax Rules, 2026 under the Income-tax Act, 2025. The 1961 rules continue to apply to earlier years and pending matters."],["Is angel tax still payable?","The provision taxing excess share premium from resident investors was abolished with effect from 1 April 2025, and the 2025 Act has no equivalent. Check your facts with a professional."],["Do I need a valuation for every share issue?","Not always. It depends on the type of issue, the parties and the law that applies. Preferential allotments and non-resident subscriptions usually need one."],["Can a chartered accountant certify the value?","For some purposes, yes. For others, a merchant banker or registered valuer is required. It depends on the provision."]]},{slug:"financial-projections-for-cc-od-or-term-loan",title:"Financial Projections for a CC/OD or Term Loan: What Banks Check",short:"Projections for a CC/OD or term loan",desc:"How to prepare financial projections for a CC, OD or term loan: what banks check, how to set assumptions, the ratios that matter and the common errors.",date:"November 2026",iso:"2026-11-02",author:"Harivadan Dabhi",service:["business-valuation","financial-modelling-projections"],tool:"dscr-calculator",related:["cma-report-for-a-bank-loan","dscr-explained","project-report-vs-cma-report"],sources:[o,["Indian Banks' Association","https://www.iba.org.in"],["Ministry of MSME","https://msme.gov.in"]],sections:[{h:"Why projections decide the loan",ps:["A bank lends against what your business will earn, not only what it has earned. Projections are your argument that the loan will be repaid. If they are believable, the officer can sanction with confidence. If they are not, the request stalls, however good your past results were.","This guide explains what banks check in projections for a working capital limit (cash credit or overdraft) and for a term loan, and how to prepare numbers that survive questions."]},{h:"Working capital and term loans are tested differently",ps:["For a working capital limit, the bank looks at your operating cycle: how long you hold stock, how long customers take to pay and how long suppliers give you. The limit is sized to the gap. Projections therefore need sales, costs and the holding periods behind them.","For a term loan, the bank looks at whether the project's profits repay the instalments. Projections must cover the whole tenure and show interest, principal and the cash left after repayment. The key ratio is the debt service coverage ratio, covered in our [DSCR guide](/insights/dscr-explained/)."]},{h:"Start from history, not from the target",ps:["Banks compare projections with past results. Build your numbers from the last two or three years: sales growth, gross margin, expense ratios and working capital days. Then change only what you can explain. A projection that doubles sales in a year needs an order book, a capacity expansion or a contract to support it.","If you are a new business with no history, use evidence in its place: quotations, signed orders, market data and the experience of the promoters."]},{h:"The assumptions banks examine first",ul:["**Sales growth:** is it consistent with capacity, market and history?","**Gross margin:** why does it change, and does the cost of inputs support it?","**Operating expenses:** are staff, rent and overheads realistic for the volume?","**Working capital days:** do inventory, receivable and creditor days match your actual cycle?","**Capital expenditure and funding:** how will each purchase be financed?","**Interest and repayment:** do they match the proposed loan terms?"]},{h:"Ratios the bank will calculate",ps:["From your projections the bank calculates the current ratio, the debt-to-net-worth ratio, the interest coverage ratio and the DSCR for every year. Each bank has its own norms. For debt service coverage, many lenders look for an average of roughly 1.25 to 1.5 or higher, and they also look at the weakest year. Calculate these yourself first, and if a year falls short, adjust the plan or the loan structure, or explain the reason."]},{h:"Test a weaker case",ps:["Credit officers often ask what happens if sales fall by 10 or 20 per cent, or if customers pay more slowly. A good projection includes a downside case and shows that the business still meets its commitments. If it does not, consider a longer tenure, a lower loan amount or a smaller expansion.","A model built in Excel with an assumptions sheet lets you test these scenarios in minutes. See our [sample financial model](/sample-reports/financial-model/) for the layout we use."]},{h:"Common errors",ul:["Assumptions typed into formulas, so changes are hard to trace.","Interest calculated on the opening balance when the loan is repaid monthly.","Depreciation, tax or working capital left out of the cash flow.","A balance sheet that does not balance.","Growth in every year with no seasonal or cyclical dip.","Projections that do not match the figures given to the GST portal."]},{h:"How we help",ps:["We build projections in Excel with every assumption written down, link them to the CMA forms your bank uses and walk you through the result. The bank decides the sanction, but a clear, consistent set of numbers makes your case easier to understand."]}],faq:[["How many years should projections cover?","For working capital, usually two to three years. For term loans, the full repayment period."],["Should projections be conservative?","They should be realistic and supported. Overly optimistic numbers lose credibility, and overly cautious ones can reduce the limit offered."],["Can I change projections after submitting?","You can submit a revised version if the bank asks or if facts change, with a note explaining what changed."],["Do banks check projections against GST returns?","They often cross-check turnover, so keep your figures consistent."]]},{slug:"pitch-deck-for-indian-investors",title:"Pitch Deck for Indian Investors: The 12 Slides That Matter",short:"Pitch deck for Indian investors",desc:"The 12 slides an Indian investor expects in a pitch deck, what each should say, common mistakes and how to keep the numbers consistent.",date:"November 2026",iso:"2026-11-02",author:"Harivadan Dabhi",service:["business-valuation","pitch-deck"],tool:"dcf-valuation-calculator",related:["how-startups-are-valued-in-india","financial-projections-for-cc-od-or-term-loan","dpiit-startup-recognition-guide"],sources:[s,["SEBI","https://www.sebi.gov.in"],["Ministry of Corporate Affairs","https://www.mca.gov.in"]],sections:[{h:"What a pitch deck is for",ps:["A pitch deck is not meant to close an investment. It is meant to earn the next meeting. An investor may see dozens of decks in a week, so yours has to explain the business quickly, show that you understand your numbers and leave them wanting to know more.","Most decks that work have between 10 and 15 slides, one idea per slide and little text. You will present them live or send them by email, so each slide must make sense on its own. This guide lists the twelve slides that matter and what each should say."]},{h:"Slides 1 to 3: who you are, the problem and your answer",ul:["**1. Title:** company name, a one-line description of what you do, your name and contact.","**2. Problem:** the problem, who has it and how they handle it today. Use a real example, not a general statement.","**3. Solution:** what you built and why it is better, in plain language. Add a screenshot or a simple picture if it helps."],ps:["Resist the urge to explain your technology at length. Investors first want to know whether the problem is real and large."]},{h:"Slides 4 to 6: product, market and business model",ul:["**4. Product:** how it works, in three or four steps, and what is live today.","**5. Market:** who your customers are, how many there are and how you worked out the number. State your sources, and prefer a bottom-up estimate to a copied headline figure.","**6. Business model:** how you make money, your price, your margins and what a customer is worth over time."],ps:["This is where careless numbers hurt most. If your market size is a figure from a report with no link to your customers, an experienced investor will notice."]},{h:"Slides 7 to 9: traction, go to market and competition",ul:["**7. Traction:** customers, revenue, growth rate, retention and anything that shows people want the product. Use real data only, and show the date.","**8. Go to market:** how you reach customers and what it costs. Show what has worked so far.","**9. Competition:** who else solves the problem, including the alternative of doing nothing, and why customers would choose you."],ps:["Be honest about what you have not yet proved. Investors forgive early-stage gaps more easily than overstatement."]},{h:"Slides 10 to 12: financials, team and the ask",ul:["**10. Financial plan:** a three to five year summary of revenue, costs and cash, with the key assumptions. It must match your detailed model.","**11. Team:** the people, what they have done before and the roles you still need to fill.","**12. The ask:** how much you are raising, what you will spend it on and what milestones it will reach."],ps:["You can browse a complete example in our [sample pitch deck](/sample-reports/pitch-deck/). It uses a fictional company, and its financial slide comes from the sample financial model."]},{h:"Keep the numbers consistent",ps:["The most common reason a good idea loses an investor's trust is inconsistent numbers: revenue on the traction slide that does not match the financial plan, or a funding ask that does not fit the cash flow. Build the model first, then draw the deck from it.","If you are valuing the company for the round, make sure the valuation, the model and the deck use the same assumptions. A short [valuation walkthrough](/how-we-value-a-business/) can help you explain how you reached your number."]},{h:"Mistakes to avoid",ul:["Too many slides or too much text on a slide.","A market size copied from a headline report.","No evidence of customers or demand.","Projections that grow every year at the same steep rate.","Hiding risks instead of showing how you manage them.","Different numbers in the deck, the model and the data room."]},{h:"Before you send it",ps:["Read the deck aloud and time it. Ask someone outside your industry what the company does. Check every number against the model. Remove claims you cannot support. Then tailor the first slide or the covering email to each investor, showing you know what they fund. We design decks with a written scope and keep them consistent with your financial model."]}],faq:[["How many slides should a pitch deck have?","Usually 10 to 15. Fewer, clearer slides get read more often."],["Should I include financial projections?","Yes, a summary of three to five years, with assumptions. Keep the detailed model ready to share."],["Do I need a valuation in the deck?","Not always. Many founders state the amount they are raising and the use of funds, and discuss valuation in the meeting."],["Can a good deck guarantee funding?","No. A good deck helps you get meetings. Investors decide on the business, the team and the market."]]},{slug:"project-report-vs-cma-report",title:"Project Report vs CMA Report: Which One Does Your Bank Need?",short:"Project report vs CMA report",desc:"The difference between a project report and a CMA report, what each contains, when banks ask for one or both and how to prepare them together.",date:"November 2026",iso:"2026-11-02",author:"Harivadan Dabhi",service:["business-valuation","cma-report"],tool:"working-capital-mpbf-calculator",related:["what-is-a-cma-report","cma-report-for-a-bank-loan","financial-projections-for-cc-od-or-term-loan"],sources:[i,["Indian Banks' Association","https://www.iba.org.in"],n],sections:[{h:"Two documents, two jobs",ps:["Business owners often hear their bank ask for a project report in one conversation and a CMA report in the next, and wonder if they are the same. They are not. They answer different questions, and for some loans the bank needs both.","A project report describes a project or a business: what it is, why it will work, how much it will cost and how it will be funded. A CMA report presents the financial data in the bank's fixed format so that the credit officer can assess it against lending norms. This guide explains the difference."]},{h:"What a project report contains",ps:["A project report, sometimes called a detailed project report or DPR, tells the story of the business or project in prose and numbers."],ul:["The promoters, their experience and the business background.","The product or service, the market and the competition.","Technical details, such as machinery, capacity, location and raw materials.","The cost of the project and the means of finance: promoter's contribution and loan.","Projected profit and loss, cash flow and break-even.","Repayment schedule and the key risks."]},{h:"What a CMA report contains",ps:["A CMA report is mostly tables. It uses the bank's format to present your existing and proposed limits, your operating statement, your balance sheet analysis, your current assets and liabilities, the maximum permissible bank finance and your fund flow, over past, current and projected years. It carries few words beyond a short note on assumptions.","Our guide to [what a CMA report is](/insights/what-is-a-cma-report/) explains each form, and the [sample CMA report](/sample-reports/cma-report/) shows how it looks."]},{h:"Side-by-side",table:{head:["","Project report","CMA report"],rows:[["Main purpose","Explain and justify a project or business","Give the bank financial data in its format"],["Format","Prose, tables and charts; flexible","Fixed forms, mostly tables"],["Used for","New projects, term loans, expansion","Working capital limits and renewals; also term loans"],["Covers","Business, market, technical aspects, cost, funding, projections","Operating statement, balance sheet analysis, ratios, MPBF, fund flow"],["Prepared by","Promoter with a finance or technical consultant","Promoter with an accountant or finance professional"]]},ps:["Both use the same numbers, so they must agree."]},{h:"Which does your bank need?",ps:["It depends on the loan, the bank and the amount."],ul:["**New business or a new project term loan:** usually a project report, plus CMA data or a projected financial statement set.","**Working capital limit for an existing business:** usually CMA data and recent financial statements; a short business note may be enough.","**Small loans and government schemes:** a simpler project report in the scheme's format may be all that is required.","**Large limits:** both, with additional reports such as stock audits and inspections."],ps:["Ask the bank for its checklist before you start, so you prepare only what it will read."]},{h:"Prepare them together",ps:["The best way to avoid mismatches is to build one financial model and draw both documents from it. Assumptions, projections, ratios and the repayment schedule then stay consistent. A change in one assumption flows to every table.","If the bank asks for changes, you update the model once and regenerate both. Our [financial modelling](/services/business-valuation/financial-modelling-projections/) service builds this kind of linked model."]},{h:"Common problems",ul:["The project report says one thing about sales and the CMA another.","The cost of the project differs between the two documents.","The repayment schedule in the project report does not match the loan terms in the CMA.","Technical details, such as capacity, do not support projected sales.","Promoters' contribution is not clearly shown."]},{h:"Next steps",ps:["Tell us the loan you need and the bank you are approaching. We tell you which documents to prepare, prepare them from one model and keep them consistent. The bank decides the sanction; our job is to give it a complete, clear case."]}],faq:[["Is a CMA report mandatory?","Not always. Banks ask for it for working capital limits above their internal threshold. Your bank can tell you."],["Do I need both for a term loan?","Often a project report and projected financial data are needed. Whether the bank wants CMA forms depends on its policy."],["Who signs the reports?","The promoter signs. Some banks also ask for a chartered accountant's certificate on the financial data."],["Can the same consultant prepare both?","Yes, and it reduces the risk of mismatches."]]},{slug:"dscr-explained",title:"DSCR Explained: How Banks Judge Your Repayment Capacity",short:"DSCR explained",desc:"What the debt service coverage ratio is, the formula banks use, a worked example, typical ranges, why the lowest year matters and how to improve DSCR.",date:"November 2026",iso:"2026-11-02",author:"Harivadan Dabhi",service:["business-valuation","cma-report"],tool:"dscr-calculator",related:["financial-projections-for-cc-od-or-term-loan","cma-report-for-a-bank-loan","what-is-a-cma-report"],sources:[i,["Indian Banks' Association","https://www.iba.org.in"],["Ministry of MSME","https://msme.gov.in"]],sections:[{h:"What DSCR measures",ps:["The debt service coverage ratio, or DSCR, answers one question: does the business earn enough cash to pay the loan instalments due in a year? A DSCR of 1.0 means the cash earned equals the payments due. Below 1.0, profits do not cover repayments. Above 1.0, there is a cushion.","Lenders look at DSCR in every term-loan proposal, because it shows repayment capacity more directly than profit alone. This guide explains the formula, gives a worked example and shows how to improve a weak ratio."]},{h:"The formula banks use",ps:["The common bank formula is: DSCR = (net profit after tax + depreciation + interest on term loan) divided by (principal repayment + interest on term loan).","The numerator is the cash available for repayment. Depreciation is added back because it reduces profit but does not take cash out of the business, and interest is added back because it is part of what you must pay. The denominator is what you must pay in the year: the instalment of principal plus the interest. Banks sometimes add other non-cash items to the numerator, so confirm your bank's version."]},{h:"A worked example",ps:["Suppose a fictional business shows these figures for a year, in rupees lakh: profit after tax 14.7, depreciation 22, interest 11 and principal repayment 18.","Cash available = 14.7 + 22 + 11 = 47.7. Payments due = 18 + 11 = 29. DSCR = 47.7 \xf7 29 = 1.64. The business covers its repayment 1.64 times. Try your own numbers in our free [DSCR calculator](/tools/dscr-calculator/), which works year by year and draws a chart."]},{h:"What range do banks want?",ps:["Many lenders look for an average DSCR of roughly 1.25 to 1.5 or higher over the loan period. This is an indicative range and not a regulatory rule. Each bank sets its own norm, which can vary by industry, loan type and your track record.","Stable businesses with predictable cash flow may be accepted at a lower ratio. Cyclical or younger businesses may be asked for a higher one."]},{h:"Average DSCR and the weakest year",ps:["Banks look at the average across the loan and also at the lowest year. A comfortable average can hide a year in which the cash does not cover the instalment, usually the first year after a moratorium or a year with heavy capital spending. Many credit officers want the minimum DSCR to stay above 1.0 and often above a stated floor.","That is why you should look at DSCR year by year, not only the average."]},{h:"DSCR is not the only ratio",ps:["Banks look at DSCR alongside the interest coverage ratio, which compares operating profit with interest; the current ratio, which compares current assets with current liabilities; and the debt-to-net-worth ratio, which shows how much of the funding is borrowed. A strong DSCR with a weak current ratio can still raise questions about liquidity. A [CMA report](/insights/what-is-a-cma-report/) presents all of them together."]},{h:"How to improve a weak DSCR",ul:["**Lengthen the tenure:** smaller instalments raise the ratio, although total interest rises.","**Reduce the loan:** a smaller loan or a higher promoter contribution lowers payments.","**Ask for a moratorium:** a repayment holiday during the build-up phase, if the bank agrees.","**Improve profit credibly:** price, cost or volume changes supported by evidence, not by assumption alone.","**Phase the capital spending:** spreading purchases over time reduces the funding needed upfront."],ps:["Whatever you change, reflect it consistently in your projections so the bank sees one coherent plan."]},{h:"Common errors",ul:["Using profit before tax instead of profit after tax.","Leaving out interest in the numerator or the denominator.","Treating working capital interest as part of the term loan.","Calculating DSCR only for the average and ignoring the weakest year.","Using a repayment schedule that does not match the sanction terms."]}],faq:[["Is a DSCR of 1.25 enough?","Many lenders look for around 1.25 to 1.5 or higher, but each bank sets its own norm. Confirm with your lender."],["Why is depreciation added back?","It is a non-cash expense, so the cash available is higher than profit alone suggests."],["Does DSCR apply to working capital loans?","It is mainly used for term loans. Working capital limits are assessed with MPBF and the current ratio."],["Can DSCR be below 1 in some years?","A year below 1.0 means profits do not cover repayment that year. Banks may accept it only with an explanation and a plan."]]},{slug:"tender-eligibility-documents-checklist",title:"Tender Eligibility Documents: A Complete Checklist for MSMEs",short:"Tender eligibility documents",desc:"The documents an MSME needs to bid for government and PSU tenders: registrations, financial proofs, experience certificates, EMD and common causes of rejection.",date:"November 2026",iso:"2026-11-02",author:"Harivadan Dabhi",service:["get-certified","tender-documentation-eligibility"],tool:"tender-eligibility-check",related:["gst-registration-documents-checklist","dscr-explained","dpiit-startup-recognition-guide"],sources:[["Government e-Marketplace (GeM)","https://gem.gov.in"],["Central Public Procurement Portal","https://eprocure.gov.in"],n,s],sections:[{h:"Why documents decide tenders",ps:["Most tenders are lost on paperwork, not on price. A tender sets conditions on turnover, experience and registration, and an evaluator checks each one against the documents you upload. If a document is missing, expired or does not match your bid, the bid can be rejected before the price is opened.","This checklist covers the documents MSMEs most often need for government and public sector tenders. Every tender is different, so always read the tender document, and use this as a starting point to organise your file."]},{h:"Registrations and identity",ul:["**PAN** of the business and **GST registration**, with recent returns filed.","**Udyam registration**, if you claim MSE benefits.","**Startup recognition** from DPIIT, if you claim startup relaxations.","**Registration on the portal**, such as GeM or the relevant e-procurement portal, with a **digital signature certificate** for the signatory.","**Company or firm documents**: incorporation certificate, partnership deed or LLP agreement, and a board resolution or power of attorney authorising the signatory."]},{h:"Financial documents",ul:["Audited financial statements for the years the tender specifies, usually the last three.","A **turnover certificate** from a chartered accountant, often with a UDIN, if the tender asks for it.","A **net worth** statement, where required.","Income tax returns, GST returns and bank statements for cross-checks.","A **solvency certificate** from the bank, if the tender asks for one."],ps:["Check how the tender defines turnover: it may mean turnover from similar work only, or total turnover. Use the figure the clause asks for."]},{h:"Experience and technical documents",ul:["Work orders, completion certificates and client satisfaction letters for **similar work** of the value and period the tender asks for.","Technical specifications, datasheets, product catalogues or test reports for goods.","Manufacturer authorisation or dealer certificates, where applicable.","Quality certifications such as ISO, if the tender asks for them.","A list of machinery, staff and facilities, if the tender asks for it."],ps:["Make sure the certificates name the work, the value and the dates clearly. A certificate that says only that you worked with a client may not satisfy the similar-work clause."]},{h:"EMD, bid security and fees",ps:["Most tenders require earnest money deposit (EMD) or a bid security, and a tender fee. EMD may be paid online or through a bank guarantee. Micro and small enterprises may be exempt from EMD in procurement by central ministries, departments and public sector enterprises, and recognised startups may get relaxations on turnover and experience. These exemptions depend on the tendering body and need the right certificate uploaded.","Our free [tender eligibility self-check](/tools/tender-eligibility-check/) shows the relevant notes with their sources and the dates we checked them."]},{h:"Declarations and forms",ul:["Undertakings that you are not blacklisted or debarred.","Affidavits and declarations in the format given in the tender, on the required stamp paper if specified.","Integrity pact or code of conduct forms, if the tender includes them.","The price bid in the exact format of the tender, usually kept separate from the technical bid.","Any pre-bid clarifications and corrigenda you have acknowledged."]},{h:"Common reasons for rejection",ul:["A missing or expired registration or certificate.","Turnover or experience below the stated requirement.","Documents not signed, stamped or uploaded in the right format.","A name or address that does not match across documents.","Late submission or a failed upload near the deadline.","A price quoted in the technical bid or outside the required format."]},{h:"Organise your file",ps:["Keep one folder per tender, with documents named as the tender asks and a checklist of each clause. Renew certificates before they expire and keep a master set of registrations, financial statements and experience letters for reuse. Upload early, because portals slow down in the last hours.","We review the full tender, tell you where there is a gap, prepare the documents and submit with your approval. Award decisions rest with the tendering authority, so we cannot promise a win. Read more on our [tender services](/tender-services/) page."]}],faq:[["Do MSMEs have to pay EMD?","Micro and small enterprises may be exempt from EMD in procurement by central bodies. Other bodies apply their own policies, and the exemption needs the correct certificate."],["How many years of financials do tenders ask for?","Usually the last three financial years, but each tender states its own requirement."],["Is a digital signature mandatory?","Most e-tenders require a digital signature certificate to sign and submit the bid."],["Can I bid without the required experience?","Some tenders allow joint ventures or relax the condition for startups. Check the clauses and ask a pre-bid query."]]},{slug:"dpiit-startup-recognition-guide",title:"DPIIT Startup Recognition: Eligibility, Benefits and Common Rejections",short:"DPIIT startup recognition",desc:"DPIIT startup recognition explained: who is eligible, the benefits, the documents needed, how to apply and the common reasons for rejection.",date:"November 2026",iso:"2026-11-02",author:"Harivadan Dabhi",service:["get-certified","startup-india-dpiit"],tool:"pvt-ltd-vs-llp-vs-opc",related:["private-limited-llp-or-opc","pitch-deck-for-indian-investors","tender-eligibility-documents-checklist"],sources:[s,["DPIIT","https://www.dpiit.gov.in"],["Income Tax Department","https://incometaxindia.gov.in"]],sections:[{h:"What DPIIT recognition is",ps:["The Department for Promotion of Industry and Internal Trade (DPIIT) recognises eligible entities as startups under the Startup India initiative. Recognition is a certificate that lets you access the benefits the government offers to startups, although each benefit has its own conditions and some need a separate application.","It is not a licence to operate or a guarantee of funding. This guide explains who qualifies, what the benefits are and how to avoid the common reasons applications are rejected. Rules are updated through notifications, so check the Startup India site for the current position."]},{h:"Who is eligible",ps:["The conditions have been set by DPIIT notification and have been revised over time. In general, an entity must meet these tests, and you should check the current text before applying."],ul:["It must be a Private Limited company, a registered partnership firm or an LLP.","It must be within the period allowed from its date of incorporation or registration, which the notification states.","Its annual turnover must not have exceeded the limit in the notification in any financial year since incorporation.","It must be working towards innovation, development or improvement of products, processes or services, or have a scalable business model with high potential for employment or wealth creation.","It must not have been formed by splitting up or reconstructing an existing business."]},{h:"Benefits",ps:["The benefits depend on your situation, and some need extra approvals."],ul:["**Self-certification** under selected labour and environment laws, subject to the conditions.","**Intellectual property support:** rebates on patent and trademark filing fees and access to facilitators.","**Public procurement:** relaxation of prior turnover and experience requirements in many government tenders, if quality and technical specifications are met.","**Tax benefits:** certain income tax exemptions are available to eligible startups only after a separate approval, so recognition alone does not grant them.","**Funding access:** eligibility for government-backed schemes and networks, though funding itself is decided by the investors or institutions."],ps:["Do not assume that recognition gives every benefit. Confirm each one against its own scheme conditions."]},{h:"Documents you need",ul:["Certificate of incorporation or registration, or the partnership deed.","PAN of the entity and details of directors or partners.","A brief description of the business and what makes it innovative or scalable.","A website or pitch deck, or a supporting document that shows the product or service.","Recommendation or supporting documents, if you apply for specific schemes."]},{h:"How to apply",ps:["The application is made online on the Startup India portal. You register the entity, fill in the details of the business, upload the documents and submit. The department may ask for clarifications, and you must reply within the time given. If the application is approved, you receive a recognition certificate with a number.","Keep the description of the business clear and specific. Explain what is new about your product or process, who your customers are and why the model can grow. Our [startup recognition service](/services/get-certified/startup-india-dpiit/) prepares and files the application with a written scope first."]},{h:"Common reasons for rejection or queries",ul:["The business description is generic or reads like an ordinary trading business.","The entity type is not eligible, such as a proprietorship.","The entity is beyond the age or turnover limit.","The business was formed by splitting or reconstructing an existing business.","The documents are missing, unclear or inconsistent.","The objects in the incorporation papers do not match the business described."]},{h:"After recognition",ps:["Use the recognition number when claiming benefits on other portals, such as tender portals and intellectual property filings. Keep your records current, because the department may ask you to update details, and the recognition can be withdrawn if the conditions are not met.","If you also want tax benefits, plan for the separate application and its eligibility window, and take professional advice before you rely on them. If you are raising money, consider how the structure you chose affects investors, and read our guide on [choosing a business structure](/insights/private-limited-llp-or-opc/)."]}],faq:[["Is DPIIT recognition mandatory for a startup?","No. It is optional. You apply if you want access to the benefits."],["Does recognition give a tax exemption automatically?","No. Certain tax exemptions need a separate approval and have their own eligibility conditions."],["Can a proprietorship get recognition?","No. Eligible entities are Private Limited companies, registered partnership firms and LLPs."],["How long does it take?","It varies. Many applications are decided within a few weeks, and queries can add time."],["Is there a fee?","The portal application has not historically carried a government fee, but check the current position. Professional fees, if you use a consultant, are separate."]]},{slug:"private-limited-llp-or-opc",title:"Private Limited, LLP or OPC: choosing a business structure",short:"Private Limited, LLP or OPC",desc:"A plain comparison of Private Limited, LLP and One Person Company: ownership, funding, compliance, liability and which fits your plans.",date:"October 2026",iso:"2026-10-19",updated:"2026-11-02",author:"Harivadan Dabhi",service:["start-a-business","private-limited-company-registration"],tool:"pvt-ltd-vs-llp-vs-opc",related:["gst-registration-documents-checklist","dpiit-startup-recognition-guide","how-startups-are-valued-in-india"],checklist:["Company registration document checklist","/downloads/company-registration-document-checklist.pdf"],sources:[["Ministry of Corporate Affairs","https://www.mca.gov.in"],["LLP portal (MCA)","https://www.llp.gov.in"],["Companies Act, 2013 (India Code)","https://www.indiacode.nic.in"]],sections:[{h:"Why the structure matters",ps:["The structure you choose decides who can own the business, whether you can take equity investment, how much compliance you carry every year and how banks and large customers see you. It is cheaper to choose well on day one than to convert later.","There is no single best structure. The right one depends on who the owners are, whether you plan to raise equity funding, whether you want to give employee stock options and how much annual compliance you are ready to handle. This guide compares the three most common structures for Indian startups and small businesses: the Private Limited company, the Limited Liability Partnership (LLP) and the One Person Company (OPC)."]},{h:"Private Limited company",ps:["A Private Limited company is a separate legal entity owned through shares. The owners (shareholders) are separate from the people who run it (directors), although in a small company the same people usually do both.","It needs at least two directors and at least two shareholders, and at least one director must be a resident in India. It can have up to 200 members, can issue different classes of shares and can grant ESOPs. For these reasons it is the usual structure for startups that expect to raise equity from angels or venture investors, and most investors are comfortable with it."],ul:["**Owners:** at least two shareholders and two directors.","**Funding:** can issue shares to investors and give ESOPs.","**Compliance:** annual accounts, statutory audit, annual returns with the Registrar of Companies, board meetings and director KYC.","**Liability:** limited to the unpaid amount on the shares held."]},{h:"Limited Liability Partnership (LLP)",ps:["An LLP combines the flexibility of a partnership with limited liability for its partners. It is a separate legal entity, and the partners agree their roles and profit share in an LLP agreement.","It needs at least two partners, with at least two designated partners, one of whom must be a resident in India. Annual compliance is lighter than for a company: an annual return and a statement of accounts and solvency, with an audit only above the prescribed turnover or contribution limits. The main limit is that an LLP cannot issue shares, so it cannot give ESOPs, and most equity investors prefer a company. Professional firms and small businesses that do not plan to raise equity often choose an LLP."]},{h:"One Person Company (OPC)",ps:["An OPC is a company with a single shareholder. It suits a solo founder who wants limited liability and a separate legal entity without bringing in a second owner.","An OPC must name a nominee who would take over if the owner cannot continue. It has company-style compliance, though some requirements, such as the number of board meetings, are relaxed compared with a Private Limited company. The rules on when an OPC must or may convert into another form have changed over the years, so check the current position with the Ministry of Corporate Affairs or a professional before you rely on an OPC for the long term. If you expect a co-founder or investors soon, you may prefer to start as a Private Limited company."]},{h:"Side-by-side comparison",ps:["Use this table as a first filter. It is general information, not a recommendation."],table:{head:["","Private Limited","LLP","OPC"],rows:[["Minimum owners","2 shareholders and 2 directors","2 partners (2 designated)","1 member plus a nominee"],["Issue shares or ESOPs","Yes","No","Yes, to the single member"],["Equity fundraising","The common structure","Difficult without shares","Limited; usually converts first"],["Annual compliance","Highest: audit, ROC filings, board meetings","Lower: annual return, accounts statement","Company-style, with some relaxations"],["Audit","Required","Only above prescribed limits","Required"],["Liability of owners","Limited","Limited","Limited"],["Best fit","Startups, growth businesses","Small teams, professional firms","Solo founders"]]}},{h:"Which one should you choose?",ps:["Start with your funding plan. If you may raise equity from investors, or want to give ESOPs to your team, a Private Limited company is usually the safer choice because investors expect it. If you will not issue shares and want lighter compliance, an LLP can make sense. If you are a solo founder and want a company with limited liability, an OPC is an option, though many founders choose a Private Limited company with a second director to keep growth options open.","Then check the other factors: do you need credibility with large clients or banks, where Private Limited companies are most familiar; do foreign investors or foreign owners come in, where a Private Limited company is the usual route; and how much compliance effort you can manage. Our free [business structure chooser](/tools/pvt-ltd-vs-llp-vs-opc/) turns these questions into a suggestion with reasons."]},{h:"Cost and time",ps:["Costs depend on authorised capital, the state of registration, professional fees and the number of directors or partners. Government fees and stamp duty vary, so we show them separately in our written scope instead of quoting a single figure here. Incorporation usually takes a few working days to a few weeks after your documents are complete, depending on name approval and the authority's queries.","Whichever structure you choose, plan for the work after incorporation: opening a bank account, PAN and TAN, GST if needed, and your first annual filings. Missing them leads to penalties and late fees."]},{h:"Common mistakes to avoid",ul:["Choosing an LLP and then finding that an investor wants shares.","Choosing an OPC and not planning for what happens when a co-founder joins.","Registering the entity before agreeing who owns what, which forces a costly change later.","Ignoring annual compliance until a notice arrives.","Using an address without the documents the registrar accepts."]},{h:"Next steps",ps:["If you are ready to register, our team prepares and files the incorporation with a written scope, fee and timeline before any work starts. Tax treatment, thresholds and eligibility rules change from time to time, so confirm the current position with a qualified professional before you decide."]}],faq:[["Can an LLP raise venture capital?","An LLP cannot issue shares, and most venture investors prefer a company, so startups seeking equity usually choose a Private Limited company."],["Can I convert from one structure to another later?","Conversions are possible but take time and cost money. It is usually cheaper to choose the structure that fits your three-year plan at the start."],["Which structure has the lowest compliance?","An LLP generally has lighter annual filings and audits only above prescribed limits."],["Do I need two directors for a Private Limited company?","Yes. A Private Limited company needs at least two directors and two shareholders, and at least one director resident in India."]]},{slug:"gst-registration-documents-checklist",title:"GST registration: documents checklist",short:"GST registration documents",desc:"The documents most applicants need for GST registration, thresholds by state type, entity-specific papers and the common reasons applications are rejected.",date:"October 2026",iso:"2026-10-19",updated:"2026-11-02",author:"Harivadan Dabhi",service:["start-a-business","gst-registration"],tool:"gst-registration-checker",related:["private-limited-llp-or-opc","tender-eligibility-documents-checklist","dscr-explained"],sources:[["GST Portal","https://www.gst.gov.in"],["CBIC GST","https://cbic-gst.gov.in"],["Central GST Act, 2017 (India Code)","https://www.indiacode.nic.in"]],sections:[{h:"Do you need to register at all?",ps:["Before you collect documents, check whether registration is required. Registration depends on the kind of supply you make, your annual turnover, the state you operate in and a few situations that require registration whatever your turnover.","The basic turnover limits differ for goods and services, and they are lower in certain special category states. Registration is also generally required if you supply goods to other states or sell through an e-commerce operator, subject to the exceptions in the law. Our free [GST registration checker](/tools/gst-registration-checker/) shows the threshold for your state with its source and the date we last checked it."]},{h:"Thresholds by state type",ps:["For ordinary states, the limit is Rs 40 lakh of aggregate turnover for suppliers of goods and Rs 20 lakh for suppliers of services. Special category states have lower limits for some supplies, and a few special category states use the higher goods limit. The lists are set by notification, and they have changed over time, so confirm your state on the CBIC or GST portal before you decide not to register.","Aggregate turnover covers all taxable and exempt supplies and exports under the same PAN across India, so count every business line, not only the one you are registering."],table:{head:["Supply","Ordinary states","Special category states"],rows:[["Goods","Rs 40 lakh","Rs 20 lakh in most; Rs 40 lakh in a few"],["Services","Rs 20 lakh","Rs 10 lakh"],["Goods to another state","Registration generally required","Registration generally required"],["Through an e-commerce operator","Registration generally required","Registration generally required"]]}},{h:"Core documents for every applicant",ps:["Most applications need the following, whatever the entity type."],ul:["**PAN** of the business or proprietor.","**Aadhaar** of the proprietor, partners or directors, with the mobile number and email linked for verification.","**Photograph** of each promoter, partner or director.","**Proof of the place of business**: a rent agreement with the owner's consent and a recent utility bill, or property papers if owned.","**Bank proof**: a cancelled cheque or the first page of a bank statement showing the account holder's name and number.","**Authorisation**: a letter or board resolution naming the authorised signatory."]},{h:"Documents by entity type",ps:["Different entities add different papers."],table:{head:["Entity","Extra documents"],rows:[["Proprietorship","Proprietor's PAN, Aadhaar and photo; business name proof if any"],["Partnership firm","Partnership deed, firm PAN, partners' PAN and Aadhaar"],["LLP","LLP agreement, incorporation certificate, designated partners' documents"],["Private Limited or OPC","Incorporation certificate, MOA and AOA, board resolution, directors' documents"]]}},{h:"Proof of business premises",ps:["The place-of-business document is the one that most often needs a second attempt. If the premises are rented, you need the rent agreement and the owner's consent or no-objection letter with a recent utility bill in the owner's name. If the premises are owned, a recent property tax receipt or electricity bill can serve. For shared or virtual offices, make sure the agreement states the exact address and the authority's requirements are met before applying.","The address on the application must match the documents exactly, including the pin code and the name of the owner."]},{h:"Common reasons applications are rejected or queried",ul:["The name on PAN, Aadhaar and bank proof does not match.","The address proof is missing, expired or in a different name without a consent letter.","The photograph or document is unclear or in the wrong format.","The authorised signatory's details do not match the authorisation.","The nature of business does not match the HSN or service code chosen.","Aadhaar authentication was skipped or the linked mobile number is not with the applicant."]},{h:"After registration",ps:["Once you receive the GSTIN, display the certificate and number at your place of business, issue tax invoices with the required details and file returns on time. Returns are due monthly or quarterly depending on your scheme and turnover, and late filing carries a fee and interest. If you registered voluntarily below the threshold, the same obligations apply.","Keeping your books matched to your returns every month avoids the mismatches that lead to notices. Our [GST return filing](/services/stay-compliant/gst-return-filing/) service sets up a calendar and handles filing with your approval."]}],faq:[["Can I register for GST voluntarily below the threshold?","Yes. Many businesses register to claim input tax credit or to sell to buyers who need a GST invoice. The same filing obligations apply."],["How long does GST registration take?","It usually takes a few working days if documents are in order. Queries from the officer can add time."],["Is a rent agreement enough for address proof?","A rent agreement is usually accompanied by a recent utility bill in the owner's name and the owner's consent letter."],["Do I need a separate registration for each state?","Yes. GST registration is state-wise under the same PAN if you operate in more than one state."]]},{slug:"what-is-a-cma-report",title:"What is a CMA report and when do banks ask for it?",short:"What is a CMA report",desc:"What a CMA report is, which forms it contains, the ratios banks check, the documents to prepare and when banks ask for it.",date:"October 2026",iso:"2026-10-19",updated:"2026-11-02",author:"Harivadan Dabhi",service:["business-valuation","cma-report"],tool:"working-capital-mpbf-calculator",related:["cma-report-for-a-bank-loan","dscr-explained","project-report-vs-cma-report"],checklist:["CMA report document checklist","/downloads/cma-report-document-checklist.pdf"],sources:[["Reserve Bank of India","https://www.rbi.org.in"],["Indian Banks' Association","https://www.iba.org.in"],["Ministry of MSME","https://msme.gov.in"]],sections:[{h:"What a CMA report is",ps:["CMA stands for Credit Monitoring Arrangement. A CMA report is the set of financial data a bank uses to assess a loan or limit request, usually for working capital. It presents your past results, the current year's estimate and your projections in a fixed format, so that the bank can compare you with its lending norms and with other borrowers.","It is not a narrative document. It is a set of tables, with a short note on assumptions, that answers the bank's basic questions: how much finance do you need, how will your business use it and how will you repay it."]},{h:"When banks ask for it",ps:["Banks usually ask for CMA data when you apply for a new cash credit or overdraft limit, when you ask for an enhancement or renewal, when you move to another bank and when a limit is large enough that a full credit assessment is required. The threshold at which a bank asks for a full CMA depends on its policy. For smaller limits, banks may use a simpler format based on turnover.","Even when the bank does not insist, a CMA report helps you decide how much finance to ask for and prepares you for the questions you will face."]},{h:"The forms in a CMA report",ps:["The standard format has six forms. Banks may adapt it, so use the version your bank gives you."],table:{head:["Form","What it covers"],rows:[["Form I","Particulars of existing and proposed limits, and security"],["Form II","Operating statement: sales, costs and profit over past, current and projected years"],["Form III","Analysis of the balance sheet: liabilities and assets"],["Form IV","Comparative statement of current assets and current liabilities"],["Form V","Computation of the maximum permissible bank finance (MPBF)"],["Form VI","Fund flow statement: sources and uses of funds"]]}},{h:"The ratios banks look at",ps:["From these forms, the bank calculates a few ratios. The common ones are the current ratio, which compares current assets with current liabilities; the debt-to-net-worth ratio, which shows how much of the funding is borrowed; the interest coverage ratio and the debt service coverage ratio, which show whether profits cover interest and repayments; and the holding periods for inventory, receivables and creditors. Each bank sets its own norms, and they differ by industry. As a rough guide for a current ratio, many banks look for something above 1.2 to 1.33, and our [DSCR explained](/insights/dscr-explained/) guide covers repayment ratios in detail."]},{h:"How MPBF is worked out",ps:["MPBF is the maximum permissible bank finance. Under the second method of lending, it equals 75 per cent of current assets less other current liabilities, so the business funds the remaining 25 per cent of current assets from long-term sources. Under the turnover method used for smaller limits, working capital need is taken as 25 per cent of projected turnover, with the bank financing up to 20 per cent and the promoter bringing 5 per cent. Our free [working capital and MPBF calculator](/tools/working-capital-mpbf-calculator/) shows both side by side.","These are standard methods, but the bank decides which one applies and may apply its own policy."]},{h:"Documents to prepare",ul:["Financial statements for the last two to three years, audited or provisional.","Projections for the next two to five years with the reasoning behind them.","Stock statement and debtor and creditor lists with ageing.","Bank statements for the last 12 months and details of existing loans.","GST returns and income tax returns for the same period.","Details of any machinery or expansion plans, with quotations."]},{h:"Common mistakes",ul:["Projections that jump far above past growth with no reason given.","Different holding periods used in different years without an explanation.","A balance sheet that does not balance, or schedules that do not add up to the totals.","Ignoring existing loans or related-party balances.","Submitting numbers that do not match the GST returns or bank statements."]},{h:"How we can help",ps:["We prepare CMA data in your bank's format with a written scope first, built from your own documents and your assumptions. You receive Excel and PDF files and a short note for the bank meeting. We do not promise a sanction, because the bank decides using its own criteria. You can see what the output looks like in our [sample CMA report](/sample-reports/cma-report/) for a fictional company. If your bank has its own format, send it to us at the start so we can match it exactly and avoid rework later."]}],faq:[["Is a CMA report the same as a project report?","No. A CMA report is financial data in the bank's format. A project report describes a project in detail, including technical and market aspects. Banks may ask for both."],["Who prepares a CMA report?","Usually the borrower with a chartered accountant or a finance professional. The bank reviews it."],["How far ahead should projections go?","Banks usually ask for the next two to five years, depending on the facility. Term loans need projections for the full repayment period."],["Does a CMA report guarantee a loan?","No. The bank decides using its own credit criteria. A complete, consistent report supports your case."]]},{...m,slug:"documents-required-for-cma-report",title:"Documents Required for a CMA Report: Complete Checklist",short:"Documents required for a CMA report",desc:"The documents a CMA report needs for a bank loan: financial statements, stock and debtor lists, loan details and what to check before you hand them over.",service:["business-valuation","cma-report"],tool:"working-capital-mpbf-calculator",related:["cma-report-for-a-bank-loan","what-is-a-cma-report","financial-projections-for-cc-od-or-term-loan"],checklist:["CMA report document checklist","/downloads/cma-report-document-checklist.pdf"],sources:[c,d,l],sections:[{h:"Why the document list matters",ps:["A CMA report is only as reliable as the papers behind it. The data in it must agree with your balance sheet, your stock and debtor records and your bank statements, because the credit officer will compare them. Most delays happen not in preparing the report but in finding documents that were never filed or that do not agree.","This checklist covers what most banks and CMA preparers ask for. Your bank may ask for more or in a different form, so confirm with your branch first. For the format and the steps, read our guide to the [CMA report for a bank loan](/insights/cma-report-for-a-bank-loan/)."]},{h:"Financial statements",ps:["The core of the report is your past performance. Collect these in finalised form wherever possible.","If your latest year is not yet audited, bring a provisional balance sheet and profit and loss account and say clearly that they are provisional. Banks accept this, but they will ask for the audited figures when they are ready."],ul:["Audited or finalised balance sheet and profit and loss account for the last two to three years, with schedules and notes","Provisional or unaudited figures for the current year to date","Auditor's report and tax audit report, where applicable","Computation of income and income tax returns with acknowledgements for the same years","Trial balance or ledger extracts for any figure that needs explaining"]},{h:"Working capital documents",ps:["For a working capital limit, the bank needs to see how much stock you hold, how much your customers owe and how much you owe your suppliers. These drive the assessment of your limit, so the lists must be current and tie to the balance sheet."],ul:["Stock statement with the latest month-end position, split into raw material, work in progress and finished goods where relevant","Debtor list with ageing, showing amounts outstanding by customer and period","Creditor list with ageing","Details of existing bank limits: bank, type of facility, sanctioned limit, outstanding and security given","Bank statements for all accounts for the last 12 months"]},{h:"Loan and project details",ps:["The bank will ask what the money is for and how you will repay it. A clear purpose and a realistic plan make the credit officer's job easier and shorten the discussion."],ul:["Amount and type of facility you are asking for, such as cash credit, overdraft or term loan","Purpose of the loan and, for a term loan, quotations for machinery or the project cost","Your growth assumptions for the next two to three years, with the reasons behind them","Details of existing loans, repayment schedules and any loans from directors or relatives","A short note on your business, customers, suppliers and main products"]},{h:"Statutory and identity documents",ps:["Banks also need to verify who you are and that you are compliant. Keep these ready alongside the financial papers."],ul:["PAN of the business and of the proprietors, partners or directors","Incorporation certificate, partnership deed or LLP agreement, with the memorandum and articles for a company","GST registration and the latest GST returns","Udyam registration certificate, if you are a micro or small enterprise","KYC of proprietors, partners or directors and address proof of the business place","Details of property offered as security, with title documents where the bank needs them"]},{h:"Check these before you submit",ps:["A few checks save weeks. Make sure the sales in your GST returns are close to the sales in your accounts, and be ready to explain any gap. Confirm that stock and debtor figures match the balance sheet. Check that the loan you list matches the lender's statement, and that the names and addresses are the same on every document.","If your books are behind, finish them first. A CMA built on incomplete books will have to be redone when the numbers change."]},{h:"What happens after you hand them over",ps:["We review the documents, list what is missing and agree the scope in writing. We then prepare the CMA data, the projections and the ratios, and walk you through them before you submit to the bank. The decision on the loan always rests with the bank.","If you want to see how the numbers fit together before you start, use our [working capital and MPBF calculator](/tools/working-capital-mpbf-calculator/). To have the report prepared, see our [CMA report service](/services/business-valuation/cma-report/)."]}],faq:[["Is a CMA report possible without audited accounts?","Many banks accept provisional figures for the current year but expect audited statements for earlier years. Ask your branch what it needs."],["How many years of financials does a CMA need?","Banks typically ask for the last two to three years, the current year estimate and projections, but each bank sets its own rule."],["Do I need a project report as well?","For a new project or a term loan, the bank may ask for one. We explain the difference in our guide to project reports and CMA reports."],["What if my GST sales and accounts sales differ?","Be ready to explain the gap, for example timing, advance receipts or credit notes. Unexplained gaps lead to queries."]]},{...m,slug:"mpbf-and-working-capital-assessment-explained",title:"MPBF and Working Capital Assessment Explained",short:"MPBF and working capital assessment",desc:"How banks assess working capital: the turnover method, the second method of lending, MPBF, margin and the ratios that decide your cash credit limit.",service:["business-valuation","cma-report"],tool:"working-capital-mpbf-calculator",related:["documents-required-for-cma-report","dscr-explained","cma-report-for-a-bank-loan"],sources:[c,d,l],sections:[{h:"What working capital assessment means",ps:["Working capital is the money a business needs to run day to day: to hold stock, to give credit to customers and to pay suppliers before it gets paid. When you ask a bank for a cash credit or overdraft limit, the bank first works out how much working capital your business needs and how much of that it is willing to finance.","That exercise is called working capital assessment. The result is a figure for the limit, and a margin that you must fund from your own long-term money. The methods below show how banks have traditionally arrived at it."]},{h:"The cycle behind the number",ps:["Working capital need comes from the operating cycle: how long money is tied up from buying raw material to getting paid by the customer. A business that holds stock for 60 days and gives customers 45 days of credit, while its suppliers give it 30 days, needs to fund the difference.","That is why a trader with fast stock turnover needs less working capital than a manufacturer with a long production cycle for the same sales. It is also why delays in receipts increase your need quickly."]},{h:"The turnover method",ps:["For smaller limits, many banks use a turnover-based approach. Under the commonly used version, the working capital requirement is taken as 25% of projected annual turnover. The bank finances up to 20% of turnover, and the borrower brings 5% of turnover as margin from its own funds.","For example, with projected turnover of ₹2 crore, the working capital requirement on this basis is ₹50 lakh, bank finance up to ₹40 lakh and borrower margin ₹10 lakh. The figures are for illustration only. The exact cut-off up to which a bank uses this method, and any variations, depend on its own policy."]},{h:"The second method of lending and MPBF",ps:["For larger limits, banks have traditionally looked at the balance sheet. Under the second method of lending, the maximum permissible bank finance (MPBF) is 75% of projected current assets less other current liabilities, which means current liabilities other than the bank borrowing itself. The remaining 25% of current assets is the margin the borrower funds from long-term sources.","For example, if projected current assets are ₹100 and other current liabilities, such as creditors, are ₹30, MPBF is 75 less 30, which is 45. The borrower's margin is 25. Again, this is an illustration of the formula, not a promise of what a bank will sanction."]},{h:"How the rules developed",ps:["These methods come from committees set up in earlier decades to bring discipline to bank lending. The Reserve Bank later withdrew its detailed prescriptions and allowed banks to set their own methods of assessment, and many banks continue to use the same logic or a variation of it in their own policies.","So the practical rule is to ask your branch which method it will use for a limit of your size. We cover the background and the numbers in our [guide to the CMA report](/insights/cma-report-for-a-bank-loan/)."]},{h:"Ratios the bank checks",ps:["After the limit, the bank looks at the ratios in the CMA data to judge whether the business can carry it.","Benchmarks vary by bank, industry and loan, so treat any number you read online as a rough guide and use your bank's own criteria."],ul:["Current ratio: current assets divided by current liabilities. A higher ratio means more cushion. Banks commonly look for a figure above one, and often more.","Total outside liabilities to tangible net worth: how much of the business is financed by outsiders compared with the owners.","Debt service coverage ratio (DSCR) for term loans: how well operating cash flow covers the year's interest and repayment. See our guide to [DSCR](/insights/dscr-explained/).","Inventory and receivable days, compared with industry norms and with your own past figures."]},{h:"How to prepare",ps:["Know your numbers before you meet the bank. Work out your projected turnover, your stock and debtor days and the margin you can fund. Try both methods in our [working capital and MPBF calculator](/tools/working-capital-mpbf-calculator/) to see the range. Gather the papers listed in [documents required for a CMA report](/insights/documents-required-for-cma-report/).","If you want the assessment and the full CMA data prepared in your bank's format, our [CMA report service](/services/business-valuation/cma-report/) does it with a written scope and timeline first."]}],faq:[["What is MPBF in simple words?","It is the largest amount of bank finance the second method of lending allows for your working capital: 75% of current assets less your other current liabilities."],["Is the turnover method the same as MPBF?","No. The turnover method looks at projected sales, while MPBF looks at the balance sheet. Banks may use either depending on the size of the limit and their policy."],["Will my bank sanction exactly what the formula shows?","Not necessarily. The formula gives an eligible range. The bank also looks at your track record, security, industry and its own policy."],["Why does my bank want a margin?","A margin means you fund part of your working capital yourself, which shows commitment and reduces the bank's risk."]]},{...m,slug:"complete-guide-to-cma-reports-for-bank-loans-in-india",pillar:!0,title:"Complete Guide to CMA Reports for Bank Loans in India",short:"Complete guide to CMA reports for bank loans",desc:"Everything about CMA reports for bank loans in India: what they are, the documents, the format, working capital methods, DSCR, projections and next steps.",service:["business-valuation","cma-report"],tool:"working-capital-mpbf-calculator",related:["what-is-a-cma-report","cma-report-for-a-bank-loan","documents-required-for-cma-report"],sources:[c,d,l],sections:[{h:"What this guide covers",ps:["If a bank has asked you for a CMA report, you probably have three questions: what is it, what do I need to give you, and how do I make sure the numbers are accepted? This guide answers them in order and links to the detailed articles on each part.","It is general information, not banking, tax or legal advice. Every bank has its own format and policy, so use this to prepare and then confirm the details with your branch."]},{h:"What a CMA report is",ps:["CMA stands for Credit Monitoring Arrangement. A CMA report is the set of statements a bank uses to assess a credit proposal: your past results, the estimate for the current year, projections for the coming years, the working capital assessment, the fund flow and key ratios.","Start with [what is a CMA report](/insights/what-is-a-cma-report/), which explains each form in plain language, and [project report vs CMA report](/insights/project-report-vs-cma-report/) if you are unsure which one your bank wants."]},{h:"Step 1: Gather the documents",ps:["The report depends on complete and consistent records. You need financial statements for the last two to three years, current-year provisional figures, stock and debtor lists, existing loan details, identity and statutory documents and your growth assumptions.","Our checklist in [documents required for a CMA report](/insights/documents-required-for-cma-report/) lists every item and what to check before submission."]},{h:"Step 2: Understand the format",ps:["Banks use similar structures with differences in detail, and some have their own templates. The article on the [CMA report for a bank loan](/insights/cma-report-for-a-bank-loan/) walks through the format, how to set projections and the mistakes that make banks send reports back."]},{h:"Step 3: Know how the limit is assessed",ps:["For working capital, the bank estimates how much you need and how much it will finance, by the turnover method or the second method of lending. Read [MPBF and working capital assessment explained](/insights/mpbf-and-working-capital-assessment-explained/) and try the [working capital and MPBF calculator](/tools/working-capital-mpbf-calculator/) before you meet the banker."]},{h:"Step 4: Check that you can repay",ps:["For a term loan, banks look closely at the debt service coverage ratio. See [what DSCR is and how banks use it](/insights/dscr-explained/) and our [DSCR calculator](/tools/dscr-calculator/). Weak cover is easier to fix before you apply than after a rejection."]},{h:"Step 5: Build projections you can defend",ps:["The projections must follow from your last balance sheet and rest on reasons you can explain: new capacity, confirmed orders or a larger market. Our guide to [financial projections for a CC/OD or term loan](/insights/financial-projections-for-cc-od-or-term-loan/) explains what banks check and how to set growth sensibly."]},{h:"Step 6: Get the report prepared",ps:["If you prefer to have it prepared, our [CMA report service](/services/business-valuation/cma-report/) confirms your bank's format, agrees the scope in writing, prepares the data and walks you through it. Businesses in Ahmedabad can also see our page on [CMA reports in Ahmedabad](/ahmedabad/cma-report/).","The sanction decision always rests with the bank. A well-prepared report improves your case, but it cannot promise the outcome."]}],faq:[["Who needs a CMA report?","Businesses applying for working capital limits, term loans, renewals or enhancements, when the bank asks for CMA data."],["Does every bank use the same CMA format?","No. The structure is similar but each bank may have its own template, so confirm it first."],["How far ahead should I start?","As soon as the bank asks. Gathering documents and settling the numbers usually takes longer than the preparation itself."]]},{...m,slug:"startup-valuation-and-fundraising-guide",pillar:!0,title:"Startup Valuation and Fundraising in India: The Complete Guide",short:"Startup valuation and fundraising guide",desc:"How startups are valued and funded in India: valuation methods, the pitch deck, financial model, share allotment rules and what investors check.",service:["business-valuation","startup-company-valuation"],tool:"dcf-valuation-calculator",related:["how-startups-are-valued-in-india","pitch-deck-for-indian-investors","valuing-unquoted-shares-rule-11ua"],sources:[p,u,["Income Tax Department","https://www.incometax.gov.in"]],sections:[{h:"What this guide covers",ps:["Raising money raises three questions for a founder: what is the business worth, what do investors need to see, and what do the rules say when you issue shares? This guide joins the answers and links to the detailed articles.","It is general information, not investment, legal or tax advice. Valuations used for tax, FEMA or the Companies Act must be signed by the authorised professional named in the law."]},{h:"How startups are valued",ps:["There is no single correct value for an early business. Common approaches are discounted cash flow, comparison with similar companies or deals, and for very early stages, a negotiated figure based on the team, traction and market. Each rests on assumptions, and the discussion with an investor is mostly about those assumptions.","Read [how startups are valued in India](/insights/how-startups-are-valued-in-india/) for the methods, and try the [DCF valuation calculator](/tools/dcf-valuation-calculator/) to see how discount rate and growth change the answer."]},{h:"The investor pack",ps:["Investors usually ask for a pitch deck, a financial model with assumptions you can defend, and a data room with your corporate records and contracts. These three must agree with each other, since inconsistencies lose trust quickly.","Our guide to the [pitch deck for Indian investors](/insights/pitch-deck-for-indian-investors/) explains what to include and what to leave out. Our [financial modelling service](/services/business-valuation/financial-modelling-projections/) builds the model, and our [pitch deck service](/services/business-valuation/pitch-deck/) designs the deck."]},{h:"When a valuation report is required",ps:["When a private company issues or transfers unquoted shares, the law may require a valuation by a specified professional. The tax rules on fair value of unquoted shares, including Rule 11UA and how the new Income-tax Act affects it, are covered in [valuing unquoted shares under Rule 11UA](/insights/valuing-unquoted-shares-rule-11ua/).","Company law and FEMA have their own requirements, so check which one applies to your transaction before you set the issue price."]},{h:"Getting recognised and structured",ps:["Investors prefer a clean structure. Most equity investors expect a private limited company, and startups may benefit from [DPIIT recognition](/insights/dpiit-startup-recognition-guide/) and the choice described in [Private Limited, LLP or OPC](/insights/private-limited-llp-or-opc/)."]},{h:"Get help with the numbers",ps:["Our [startup and company valuation service](/services/business-valuation/startup-company-valuation/) prepares the analysis and coordinates the signing through licensed partners where the law requires it, and our [fundraising support](/services/business-valuation/fundraising-support/) helps you prepare the pack. We do not guarantee funding. The decision to invest is the investor's."]}],faq:[["How do I know what my startup is worth?","A reasoned range from a method such as DCF or comparable companies, tested against what investors in your stage and sector actually pay."],["Do I need a valuation before I raise money?","Not always, but a reasoned valuation helps the discussion, and some share issues legally need one."],["Who signs a valuation report?","That depends on its purpose. Some need a Registered Valuer or merchant banker, as the law requires."]]},{...m,slug:"company-registration-and-compliance-guide",pillar:!0,title:"Company Registration and Compliance in India: The Complete Guide",short:"Company registration and compliance guide",desc:"How to register and stay compliant in India: choosing a structure, DPIIT recognition, GST registration, annual filings and who handles what.",service:["start-a-business","private-limited-company-registration"],tool:"pvt-ltd-vs-llp-vs-opc",related:["private-limited-llp-or-opc","dpiit-startup-recognition-guide","gst-registration-documents-checklist"],sources:[u,["GST Portal","https://www.gst.gov.in"],p],sections:[{h:"What this guide covers",ps:["Starting a business in India involves a sequence: choose the structure, register it, get your tax registrations and then keep up with the filings every year. This guide puts them in order and links to the detail.","Rules change, so confirm each step on the official portal or with a qualified professional. This is general information, not legal or tax advice."]},{h:"Step 1: Choose the structure",ps:["The structure decides who can own the business, how you raise money, how much compliance you carry and how banks see you. Read [Private Limited, LLP or OPC](/insights/private-limited-llp-or-opc/) and use the [business structure chooser](/tools/pvt-ltd-vs-llp-vs-opc/) to narrow the choice."]},{h:"Step 2: Register the entity",ps:["A company or LLP is incorporated through the Ministry of Corporate Affairs. Our services cover [private limited company registration](/services/start-a-business/private-limited-company-registration/), [LLP registration](/services/start-a-business/llp-registration/) and [One Person Company registration](/services/start-a-business/one-person-company-registration/), and each follows PAN and TAN, which you can arrange through [PAN and TAN registration](/services/start-a-business/pan-tan-registration/). Businesses in Ahmedabad can see [company registration in Ahmedabad](/ahmedabad/company-registration/)."]},{h:"Step 3: Register for GST where required",ps:["Registration depends on your turnover, the kind of supply and the state. See the [GST registration documents checklist](/insights/gst-registration-documents-checklist/), check your case in the [GST registration checker](/tools/gst-registration-checker/), and see our [GST registration service](/services/start-a-business/gst-registration/). In Gujarat, our page on [GST registration and filing in Ahmedabad](/ahmedabad/gst-registration-and-filing/) explains local points."]},{h:"Step 4: Consider startup recognition",ps:["If you qualify as a startup, DPIIT recognition can open tax and other benefits. Read the [DPIIT startup recognition guide](/insights/dpiit-startup-recognition-guide/) for eligibility and documents, and see [Startup India DPIIT recognition](/services/get-certified/startup-india-dpiit/)."]},{h:"Step 5: Stay compliant every year",ps:["After registration come the recurring duties: GST returns, TDS returns, the income tax return and, for companies and LLPs, the annual filings with the Registrar of Companies. Missing dates leads to additional fees and, in time, bigger problems. See [GST return filing](/services/stay-compliant/gst-return-filing/), [TDS returns](/services/stay-compliant/tds-returns/), [income tax return filing](/services/stay-compliant/income-tax-return-filing/) and [ROC annual filing](/services/stay-compliant/roc-annual-filing/)."]}],faq:[["Which should I register first, the company or GST?","The company or LLP first. GST registration needs the entity's PAN and incorporation papers."],["Is compliance required if my company has no turnover?","Yes. A company must file annual returns even when it has no business."],["Can AlphaZet handle every step?","We prepare and file the work, and filings needing a Chartered Accountant or Company Secretary go through licensed partner professionals."]]},{...m,slug:"government-tenders-guide-gem-e-tender-emd",pillar:!0,title:"Government Tenders in India: GeM, e-Tender and EMD Guide",short:"Government tenders guide: GeM, e-tender and EMD",desc:"How to bid for government tenders in India: where they are published, eligibility, GeM, nProcure, EMD and MSME exemptions, and how to submit a clean bid.",service:["get-certified","tender-documentation-eligibility"],tool:"tender-eligibility-check",related:["tender-eligibility-documents-checklist"],sources:[["Government e-Marketplace (GeM)","https://gem.gov.in"],["nProcure (Gujarat e-procurement)","https://www.nprocure.com"],["Central Public Procurement Portal","https://eprocure.gov.in"],l],sections:[{h:"What this guide covers",ps:["Government buyers purchase goods, services and works through published tenders and through the Government e-Marketplace. This guide explains where to find them, what eligibility means, how EMD works and how to submit a bid that is not rejected on paper.","Each tender has its own conditions, and the notice always prevails over general information such as this."]},{h:"Where tenders are published",ps:["Central departments and public sector units publish on the Central Public Procurement Portal and on their own portals. Gujarat state departments, boards and municipal bodies publish many tenders on nProcure. The Government e-Marketplace (GeM) is used for a large share of purchases of standard goods and services. Each portal has its own registration and signature requirements.","For local detail see our page on [tender services in Gujarat](/gujarat/tender-services/) and our [GeM registration and portal support](/services/get-certified/gem-registration-portal-support/)."]},{h:"Eligibility and documents",ps:["A bid is first checked against the eligibility conditions: turnover, experience in similar work, registrations and capacity. A bid that fails here is rejected before the price is opened. Our guide to [tender eligibility documents](/insights/tender-eligibility-documents-checklist/) lists the papers, and the [tender eligibility self-check](/tools/tender-eligibility-check/) helps you see where you stand."]},{h:"EMD, tender fee and MSME exemptions",ps:["Earnest Money Deposit (EMD) is a refundable amount that shows the bidder is serious, and the tender fee is a non-refundable charge for the document. Registered micro and small enterprises are exempt from both in many purchases under the public procurement policy for MSEs, with valid Udyam proof. The exact rule depends on the buyer and the notice, so read it each time. See [MSME Udyam registration](/services/get-certified/msme-udyam-registration/)."]},{h:"Submitting the bid",ps:["Upload early, check every file's name, size and format, confirm that the digital signature is valid, and save the acknowledgement. Our [tender filing and bid submission service](/services/get-certified/tender-filing-bid-submission/) and our [tender documentation and eligibility service](/services/get-certified/tender-documentation-eligibility/) handle this, and the full process is on our [tender services](/tender-services/) page. We do not promise that a bid will win. The buyer evaluates every bid on the notice."]}],faq:[["Where do I find Gujarat government tenders?","Many are published on nProcure. Central tenders are on the Central Public Procurement Portal, and many purchases happen on GeM."],["Do I need a digital signature to bid?","Yes. e-tender portals normally require a Class 3 digital signature."],["Can a new business win government work?","It can, if it meets the tender's conditions. Some tenders relax experience for startups and MSEs."]]}].map(e=>h[e.slug]?{...e,sections:[...e.sections.slice(0,-1),h[e.slug],e.sections[e.sections.length-1]]}:e).sort((e,t)=>(t.iso+(t.updated||"")).localeCompare(e.iso+(e.updated||"")));let f={name:"AlphaZet Services Private Limited",url:"https://alphazetservices.com",geo:{lat:"",lng:""},social:{gbp:"",linkedinCompany:"",instagram:""},gsc:"",phone:"9099629227",phoneIntl:"+91 90996 29227",tel:"+919099629227",wa:"919099629227",email:"contact@alphazetservices.com",gaId:"",hours:"Mon to Sat, 9:30 am to 7:00 pm IST",head:"C-701, PNTC, Times Of India Press Rd, Vejalpur, Ahmedabad, Gujarat 380015",branch:"52 Pushpak Corner, nr. Kudrat Residency, RP Camp, Naroda, Ahmedabad, Gujarat 382330"}}}]);